import heapq
from typing import List

def findCriticalNodes(pods: int, n: int, connections: List[List[int]], q: int, queries: List[List[int]]) -> List[int]:
    parent = list(range(pods + 1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for u, v in connections:
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv

    # 每个区域一个最小堆；pod 只会掉线不会恢复，所以可以懒删除
    heaps = {}
    for p in range(1, pods + 1):
        heaps.setdefault(find(p), []).append(p)  # 按编号递增追加，本身就是合法的堆
    active = [True] * (pods + 1)

    out = []
    for op, p in queries:
        if op == 2:
            active[p] = False
            continue
        if active[p]:
            out.append(p)
            continue
        h = heaps[find(p)]
        while h and not active[h[0]]:
            heapq.heappop(h)
        out.append(h[0] if h else -1)
    return out
